            // value is a ZZ32 (P-173), and one beyond it the error of its range
            BigInteger bi = new BigInteger(s.substring(1, s.length() - 1));
            String zz32 = Naming.RT_VALUES_PKG + "FZZ32";
            if (bi.bitLength() <= 31) {
                mv.visitLdcInsn(Integer.valueOf(bi.intValue()));
                mv.visitMethodInsn(Opcodes.INVOKESTATIC, zz32, "make", "(I)L" + zz32 + ";", false);
            } else {
                mv.visitLdcInsn(bi.toString());
                mv.visitMethodInsn(Opcodes.INVOKESTATIC, zz32, "makeSize", "(Ljava/lang/String;)L" + zz32 + ";", false);
            }
        } else {
            throw new Error("Invocation of magic class Method '"+oname+
                      "' ('"+name+"') seen, but op is not recognized.");
        }
    } else {
        String new_owner = xlation.getTypeName(owner);  // demangled.
        if (opcode == Opcodes.INVOKEINTERFACE && !new_owner.equals(owner) ) {
            if (new_owner.contains(Naming.LEFT_OXFORD)) {
                if (new_owner.startsWith(Naming.UNION_OX)) {
                    // replace invokeinterface with invokestatic, modify desc
                    opcode = Opcodes.INVOKESTATIC;
                    descSplice = Naming.ERASED_UNION_DESC;
                } else if (! new_owner.startsWith(Naming.ARROW_OX) &&
                    ! new_owner.startsWith(Naming.TUPLE_OX)   ) {
                    Naming.XlationData xldata =
                        icl.xlationForGeneric(new_owner);
                    String stem_sort = xldata.first();
                    if (stem_sort.equals(Naming.OBJECT_GENERIC_TAG)
                        // || stem_sort.equals(Naming.FUNCTION_GENERIC_TAG)
                        )
                        opcode = Opcodes.INVOKEVIRTUAL;
                    else {
                      // do nothing
                    }
                } else {
                	// do nothing
                }

            } else {
                String new_owner_class_name = Naming.mangleFortressIdentifier(new_owner);
                new_owner_class_name = new_owner_class_name.replaceAll("[/]", ".");
                Boolean is_interface = interfaceByClassFile(new_owner_class_name);
                if (is_interface != null) {
                    if (!is_interface) opcode = Opcodes.INVOKEVIRTUAL;
                } else try {
                    Class cl = Class.forName(new_owner_class_name, true, icl);
                    if (cl.isInterface()) {
                        // Do nothing
                    } else {
                        opcode = Opcodes.INVOKEVIRTUAL;
                    }
                } catch (ClassNotFoundException e) {
                    // Do nothing, not our problem
                }
            }
        }
        name = xlation.getMethodName(name);
        desc = xlation.getMethodDesc(desc);
        if (descSplice != null)
            desc = "(" + descSplice + desc.substring(1);
        // itf must track the (possibly rewritten) opcode: the
        // INVOKEINTERFACE -> INVOKESTATIC/INVOKEVIRTUAL rewrites above
        // retarget the call at a class, not an interface.
        mv.visitMethodInsn(opcode, new_owner, name, desc,
                           opcode == Opcodes.INVOKEINTERFACE);
    }
}

/**
 * Whether the named class is an interface, read from the access flags of
 * the class file that the loader would define for it, so that no class
 * is loaded.  The class named can be the one whose superclass this
 * expansion makes: an object that lists a trait with a self-type
 * parameter first extends the trait's default methods at itself, and a
 * load of the object here is circular.  Null where the loader finds no
 * class file of that name, as for a class that it generates.
 */
private Boolean interfaceByClassFile(String dotted_name) {
    java.io.InputStream in = icl.getResourceAsStream(Naming.dotToSep(dotted_name) + ".class");
    if (in == null) return null;
    try {
        try {
            int access = new org.objectweb.asm.ClassReader(in).getAccess();
            return (access & Opcodes.ACC_INTERFACE) != 0;
        } finally {
            in.close();
        }
    } catch (java.io.IOException e) {
        return null;
    }
}

